p3_questions = [
    ("gov_m3_01", "1960 Independence Constitution", "2010", "Under the 1960 Independence Constitution of Nigeria, the ceremonial Head of State was the:", ["Queen of England (represented by the Governor-General)", "Executive President", "Prime Minister", "Chief Justice of the Federation"], 0, "The 1960 Constitution retained the British Monarch as constitutional Head of State, represented locally by the Governor-General (Dr. Nnamdi Azikiwe).", "Easy"),
    ("gov_m3_02", "1960 Independence Constitution", "2010", "In Nigeria's First Republic (1960-1966), the Head of Government who held actual executive powers was the:", ["Prime Minister (Sir Abubakar Tafawa Balewa)", "Governor-General", "President of the Senate", "Speaker of the House"], 0, "Sir Abubakar Tafawa Balewa was the Prime Minister and Head of Government, leading the parliamentary cabinet.", "Easy"),
    ("gov_m3_03", "1960 Independence Constitution", "2012", "Under the 1960 Constitution, the highest and final court of appeal for Nigerian cases was the:", ["Judicial Committee of the Privy Council in London", "Supreme Court of Nigeria", "Federal Court of Appeal", "Regional High Court"], 0, "Appeals from the Nigerian Supreme Court went to the Judicial Committee of the Privy Council until the 1963 Republican Constitution.", "Easy"),
    ("gov_m3_04", "1963 Republican Constitution", "2010", "A fundamental change brought about by the 1963 Republican Constitution was that:", ["The Queen ceased to be Head of State and the President became Head of State", "Nigeria adopted a presidential system", "All political parties were abolished", "The Supreme Court was relocated to London"], 0, "The 1963 Constitution declared Nigeria a Federal Republic, severing monarchical ties and creating the office of the President.", "Easy"),
    ("gov_m3_05", "1963 Republican Constitution", "2011", "Under the 1963 Republican Constitution, the Supreme Court of Nigeria became the:", ["Final and highest court of appeal in the country", "Appellate body under the British Privy Council", "Legislative drafting committee", "Electoral tribunal for local councils"], 0, "The 1963 Constitution abolished appeals to the Privy Council in London and made the Nigerian Supreme Court the apex court.", "Easy"),
    ("gov_m3_06", "1963 Creation of Mid-Western Region", "2010", "The Mid-Western Region was created in 1963 out of the:", ["Western Region", "Eastern Region", "Northern Region", "Southern Cameroons"], 0, "The Mid-Western Region (later Bendel State, now Edo and Delta States) was carved out of the Western Region following a 1963 plebiscite.", "Easy"),
    ("gov_m3_07", "First Republic Politics & Crises", "2010", "The ruling federal coalition government in Nigeria at independence in 1960 was formed by the:", ["Northern People's Congress (NPC) and NCNC", "Action Group (AG) and NPC", "NCNC and Action Group (AG)", "NEPU and UMBC"], 0, "The NPC and NCNC formed a coalition government with Balewa as Prime Minister and Azikiwe as Senate President / Governor-General.", "Easy"),
    ("gov_m3_08", "First Republic: Action Group Crisis 1962", "2010", "The Action Group crisis of 1962 in the Western Region arose primarily from a political rift between:", ["Chief Obafemi Awolowo and Chief Samuel Ladoke Akintola", "Dr. Nnamdi Azikiwe and Sir Ahmadu Bello", "Herbert Macaulay and Ernest Ikoli", "Aminu Kano and Tafawa Balewa"], 0, "The ideological and leadership struggle between party leader Awolowo and Western Region Premier Akintola fractured the Action Group.", "Easy"),
    ("gov_m3_09", "First Republic: Western Crisis 1962", "2011", "Following the 1962 Action Group crisis, the Federal Government declared a state of emergency in Western Nigeria and appointed as Sole Administrator:", ["Dr. Moses Adekoyejo Majekodunmi", "Chief Obafemi Awolowo", "Chief S.L. Akintola", "Dr. Nnamdi Azikiwe"], 0, "Senator Dr. M.A. Majekodunmi was appointed Administrator of Western Nigeria during the six-month emergency period in 1962.", "Medium"),
    ("gov_m3_10", "First Republic: 1964 General Election", "2012", "In the contentious 1964 federal elections, the two grand political alliances that contested were:", ["Nigerian National Alliance (NNA) and United Progressive Grand Alliance (UPGA)", "NPC and NCNC", "UPN and NPN", "SDP and NRC"], 0, "The NNA (NPC, NNDP-Akintola, MDF) contested against the UPGA (NCNC, AG, UMBC, NEPU).", "Easy"),
    ("gov_m3_11", "Military Rule: January 15 1966 Coup", "2010", "The first military coup d'état in Nigeria took place on:", ["January 15, 1966", "July 29, 1966", "July 29, 1975", "December 31, 1983"], 0, "The January 15, 1966 coup led by Major Chukwuma Kaduna Nzeogwu toppled the First Republic civilian government.", "Easy"),
    ("gov_m3_12", "Military Rule: First Military Head of State", "2010", "Following the January 15, 1966 coup, the civilian Council of Ministers handed over state power to:", ["Major-General J.T.U. Aguiyi-Ironsi", "General Yakubu Gowon", "General Murtala Muhammed", "General Olusegun Obasanjo"], 0, "General Officer Commanding the Nigerian Army, Major-General Johnson Aguiyi-Ironsi, took over as Nigeria's first military Head of State.", "Easy"),
    ("gov_m3_13", "Military Rule: Decree 34 of 1966", "2010", "Decree No. 34 of May 1966 promulgated by the Aguiyi-Ironsi regime is historically known as the:", ["Unification Decree", "State Security Decree", "Public Order Decree", "Offensive Publications Decree"], 0, "Decree 34 abolished Nigeria's federal structure, unified the regional civil services, and converted regions into groups of provinces.", "Easy"),
    ("gov_m3_14", "Military Rule: July 1966 Counter-Coup", "2010", "The counter-coup of July 29, 1966 led to the assassination of General Aguiyi-Ironsi and the emergence of:", ["Lt. Col. (later General) Yakubu Gowon", "General Murtala Muhammed", "Major-General Muhammadu Buhari", "General Sani Abacha"], 0, "Lt. Col. Yakubu Gowon became Head of State and restored the federal structure by repealing Decree 34.", "Easy"),
    ("gov_m3_15", "State Creation: 1967 (12 States)", "2010", "On May 27, 1967, General Yakubu Gowon dissolved the four regions and created:", ["12 States", "19 States", "21 States", "36 States"], 0, "Gowon created 12 states (6 in the North, 6 in the South) to restructure the federation and weaken regional secessionist pressures.", "Easy"),
    ("gov_m3_16", "Military Rule: July 29 1975 Coup", "2010", "General Yakubu Gowon was overthrown in a bloodless coup on July 29, 1975, which brought to power:", ["Brigadier (later General) Murtala Ramat Muhammed", "General Olusegun Obasanjo", "Major-General Muhammadu Buhari", "General Ibrahim Babangida"], 0, "General Murtala Muhammed took over power in July 1975 and initiated a dynamic anti-corruption drive and transition to civil rule.", "Easy"),
    ("gov_m3_17", "Military Rule: Supreme Military Council Reform", "2011", "A notable institutional difference between Murtala Muhammed's Supreme Military Council (SMC) and Gowon's was that:", ["Military governors were excluded from the SMC to focus solely on state administration", "Civilians were made majority members", "The Chief Justice was appointed chairman", "Traditional rulers were given veto power"], 0, "Murtala restructured the SMC by excluding military governors, placing them under the newly created National Council of State.", "Medium"),
    ("gov_m3_18", "State Creation: 1976 (19 States)", "2011", "In February 1976, the Murtala Muhammed regime increased the number of states in Nigeria from 12 to:", ["19 States", "21 States", "30 States", "36 States"], 0, "Following the Justice Ayo Irikefe Panel recommendations, 7 new states were created, bringing the total to 19 states.", "Easy"),
    ("gov_m3_19", "Federal Capital Territory: Abuja", "2010", "The committee that recommended relocating Nigeria's Federal Capital from Lagos to Abuja was headed by:", ["Justice Akinola Aguda", "Justice Atanda Fatai-Williams", "Justice Udo Udoma", "Chief Jerome Udoji"], 0, "The Justice Akinola Aguda Panel (1975) selected Abuja in central Nigeria due to its neutrality, central location, and land availability.", "Easy"),
    ("gov_m3_20", "Local Government: 1976 Local Government Reforms", "2010", "The historic 1976 Local Government Reforms in Nigeria were revolutionary because they:", ["Recognized local government as an autonomous third tier of government with uniform functions nationwide", "Abolished all elected local councils", "Made traditional rulers the sole executive chairmen", "Merged local governments with state ministries"], 0, "The 1976 reforms introduced a uniform single-tier system of local government nationwide, establishing it as the third tier of the federation.", "Easy"),
    ("gov_m3_21", "Local Government: Traditional Rulers Role", "2012", "Under the 1976 Local Government Reforms, traditional rulers in Nigeria were restricted to:", ["Advisory, cultural, and ceremonial roles in Traditional Councils", "Executive chairmanship of local councils", "Passing statutory council budgets", "Commanding local police units"], 0, "Traditional rulers were stripped of direct executive/administrative powers in local councils and assigned advisory roles in Traditional Councils.", "Easy"),
    ("gov_m3_22", "1979 Constitution: Presidential System", "2010", "The Constitution of 1979 marked a major departure in Nigerian political history by introducing a:", ["US-style Executive Presidential system of government", "Westminster parliamentary cabinet system", "Confederal diarchy", "Unitary system under military decree"], 0, "The 1979 Constitution discarded the parliamentary model and adopted the Executive Presidential system.", "Easy"),
    ("gov_m3_23", "1979 Constitution: Constitutional Drafting", "2011", "The Constitution Drafting Committee (CDC) that prepared the draft of the 1979 Constitution was chaired by:", ["Chief Rotimi Williams (SAN)", "Justice Udo Udoma", "Chief Obafemi Awolowo", "Alhaji Shehu Shagari"], 0, "The '49 Wise Men' of the Constitution Drafting Committee appointed by General Murtala Muhammed were chaired by Chief Rotimi Williams.", "Medium"),
    ("gov_m3_24", "1979 Constitution: Constituent Assembly", "2011", "The 1977/1978 Constituent Assembly that debated and refined the draft 1979 Constitution was presided over by:", ["Justice Udo Udoma", "Chief Rotimi Williams", "Justice Akinola Aguda", "Dr. Joseph Wayas"], 0, "Justice Udo Udoma served as the Chairman of the 1977-1978 Constituent Assembly.", "Medium"),
    ("gov_m3_25", "1979 Constitution: Federal Character Principle", "2010", "The Federal Character Principle was entrenched in the 1979 Constitution in order to:", ["Ensure equitable representation and appointments of diverse ethnic/regional groups in public institutions", "Abolish the civil service commission", "Give the ruling party absolute power", "Enforce a single national language"], 0, "Section 14(3) of the 1979 Constitution mandated federal character to promote national unity and prevent domination by any single ethnic/regional group.", "Easy"),
    ("gov_m3_26", "1979 Constitution: Code of Conduct Bureau", "2010", "The Code of Conduct Bureau was established under the 1979 Constitution primarily to:", ["Enforce public probity, accountability, and receive asset declarations of public officers", "Arrest and prosecute criminal armed robbers", "Conduct national population censuses", "Appoint judges to the Supreme Court"], 0, "The Code of Conduct Bureau promotes ethics, probity, and transparency by monitoring the conduct and assets of public servants.", "Easy"),
    ("gov_m3_27", "1979 Constitution: Code of Conduct Tribunal", "2013", "The judicial body empowered by the constitution to try and punish public officers who breach the Code of Conduct is the:", ["Code of Conduct Tribunal", "Federal High Court", "Public Complaints Commission", "National Judicial Council"], 0, "The Code of Conduct Tribunal (CCT) exercises exclusive judicial jurisdiction to adjudicate violations of the Code of Conduct for Public Officers.", "Medium"),
    ("gov_m3_28", "1979 Constitution: Public Complaints Commission", "2010", "The Public Complaints Commission in Nigeria serves as the national:", ["Ombudsman (investigating administrative injustices and citizen grievances against public agencies)", "Revenue allocation commission", "Anti-corruption military tribunal", "Electoral monitoring panel"], 0, "Created in 1975 and entrenched in 1979, the PCC is Nigeria's ombudsman institution investigating complaints of bureaucratic abuse and maladministration.", "Easy"),
    ("gov_m3_29", "Second Republic: 1979 Presidential Election", "2010", "The first Executive President of Nigeria elected in the 1979 general elections was:", ["Alhaji Shehu Shagari", "Dr. Nnamdi Azikiwe", "Chief Obafemi Awolowo", "Mallam Aminu Kano"], 0, "Alhaji Shehu Shagari of the National Party of Nigeria (NPN) was elected Nigeria's first executive president in 1979.", "Easy"),
    ("gov_m3_30", "Second Republic: Registered Political Parties", "2010", "The five political parties originally registered by FEDECO to contest the 1979 general elections were:", ["NPN, UPN, NPP, GNPP, and PRP", "PDP, APC, APGA, LP, and ANPP", "NCNC, NPC, AG, NEPU, and UMBC", "SDP, NRC, UNCP, DPN, and GDM"], 0, "FEDECO registered five political parties for the 1979 elections: NPN, UPN, NPP, GNPP, and PRP. (NAP was registered later in 1982 for the 1983 elections).", "Easy"),
    ("gov_m3_31", "Second Republic: National Assembly Leadership", "2010", "In Nigeria's Second Republic (1979-1983), the President of the Senate was:", ["Dr. Joseph Wayas", "Chief Edwin Ume-Ezeoke", "Dr. Chuba Okadigbo", "Senator J.S. Tarka"], 0, "Dr. Joseph Wayas (NPN, Cross River) served as Senate President, while Chief Edwin Ume-Ezeoke (NPP, Anambra) was Speaker of the House of Representatives.", "Medium"),
    ("gov_m3_32", "Second Republic: NPN-NPP Accord", "2011", "To secure a working legislative majority in the National Assembly in 1979, the ruling NPN formed an alliance/accord with the:", ["Nigeria People's Party (NPP)", "Unity Party of Nigeria (UPN)", "Great Nigeria People's Party (GNPP)", "People's Redemption Party (PRP)"], 0, "The NPN and NPP entered into a post-election legislative cooperation accord in 1979, enabling the election of an NPP Speaker in the House.", "Medium"),
    ("gov_m3_33", "Second Republic: The 12 2/3 Constitutional Controversy", "2012", "The major constitutional controversy regarding the declaration of the winner in the 1979 presidential election centered on the interpretation of:", ["Two-thirds of 19 states (whether 12 2/3 meant 13 full states or 12 states plus 2/3 of a 13th state)", "The minimum age requirement for presidential candidates", "The educational qualifications of candidates", "The number of registered voters in Lagos"], 0, "The Supreme Court in Awolowo v. Shagari (1979) upheld FEDECO's declaration that obtaining 25% in 12 states and 2/3 of 25% in Kano satisfied the 12 2/3 requirement.", "Medium"),
    ("gov_m3_34", "1979 Constitution: Structure of the Senate", "2013", "Under the 1979 Constitution, each of the 19 states of the federation was represented in the Senate by:", ["5 Senators (plus 1 for FCT, total 95 members)", "3 Senators", "10 Senators", "A number proportional to state population"], 0, "The 1979 Senate comprised 5 senators per state (5 x 19 = 95). (The 1999 Constitution later modified this to 3 per state plus 1 for FCT = 109).", "Medium"),
    ("gov_m3_35", "Military Rule: December 31 1983 Coup", "2010", "The Second Republic civilian government was terminated on December 31, 1983 in a military coup that brought to power:", ["Major-General Muhammadu Buhari", "General Ibrahim Babangida", "General Sani Abacha", "General Abdulsalami Abubakar"], 0, "Major-General Muhammadu Buhari became military Head of State following the overthrow of the Shagari administration.", "Easy"),
    ("gov_m3_36", "Military Rule: Buhari Regime 1983-1985", "2011", "A notable nationwide discipline and civic re-orientation campaign launched by the Buhari/Idiagbon military regime in 1984 was the:", ["War Against Indiscipline (WAI)", "Mass Mobilization for Self-Reliance (MAMSER)", "National Orientation Agency (NOA)", "Ethical Revolution"], 0, "The Buhari regime launched WAI to tackle corruption, civil indiscipline, queue jumping, and environmental sanitation.", "Easy"),
    ("gov_m3_37", "Military Rule: Dikko Affair 1984", "2012", "Nigeria's diplomatic relations with Great Britain were severely strained in 1984 due to the:", ["Attempted kidnapping and crating of fugitive Second Republic minister Alhaji Umaru Dikko in London", "Discovery of oil in the North Sea", "Expulsion of the British High Commissioner from Lagos", "Refusal of British loans to Nigeria"], 0, "The botched diplomatic crate abduction of Umaru Dikko from London back to Lagos caused a major diplomatic standoff between Nigeria and the UK.", "Medium"),
    ("gov_m3_38", "Military Rule: August 27 1985 Coup", "2010", "Major-General Muhammadu Buhari was toppled in a palace military coup on August 27, 1985 by:", ["Major-General (later General) Ibrahim Badamasi Babangida", "General Sani Abacha", "General Oladipo Diya", "General Domkat Bali"], 0, "General Ibrahim Babangida assumed power as Nigeria's first military leader to take the title 'Military President'.", "Easy"),
    ("gov_m3_39", "Military Rule: Armed Forces Ruling Council", "2010", "The highest decision-making and legislative organ of state under the Babangida regime was the:", ["Armed Forces Ruling Council (AFRC)", "Supreme Military Council (SMC)", "Provisional Ruling Council (PRC)", "Federal Executive Council (FEC)"], 0, "Babangida replaced the SMC with the Armed Forces Ruling Council (AFRC) as the apex legislative and governing body.", "Easy"),
    ("gov_m3_40", "Third Republic Transition: Political Bureau 1986", "2011", "The Political Bureau set up by the Babangida regime in 1986 to conduct nationwide debate on Nigeria's political future was headed by:", ["Dr. Samuel J. Cookey", "Prof. Dotun Philips", "Prof. Ojetunji Aboyade", "Justice Buba Ardo"], 0, "The Cookey Commission (Political Bureau) recommended a grassroots two-party democratic system and a socialist-oriented welfare state.", "Medium"),
    ("gov_m3_41", "Third Republic: Two-Party System", "2010", "The two political parties established by the Federal Military Government for the Third Republic transition were:", ["Social Democratic Party (SDP) and National Republican Convention (NRC)", "PDP and APP", "UPN and NPN", "Action Congress and CPC"], 0, "The Babangida administration created the SDP ('a little to the left') and NRC ('a little to the right').", "Easy"),
    ("gov_m3_42", "Elections: Option A4", "2010", "The Option A4 open-ballot voting system used during the June 12, 1993 presidential election was introduced by NEC Chairman:", ["Prof. Humphrey Nwosu", "Prof. Eme Awa", "Justice Ovie-Whisky", "Prof. Attahiru Jega"], 0, "Prof. Humphrey Nwosu developed Option A4, where voters queued behind the portrait or logo of their preferred candidate.", "Easy"),
    ("gov_m3_43", "State Creation: 1987 (21 States)", "2010", "In September 1987, the Babangida administration created two new states, namely:", ["Akwa Ibom and Katsina States", "Delta and Edo States", "Yobe and Jigawa States", "Bayelsa and Ebonyi States"], 0, "Katsina (from Kaduna) and Akwa Ibom (from Cross River) were created in 1987, increasing states to 21.", "Easy"),
    ("gov_m3_44", "State Creation: 1991 (30 States)", "2011", "In August 1991, the number of states in Nigeria was increased to 30 with the creation of nine new states under:", ["General Ibrahim Babangida", "General Sani Abacha", "General Yakubu Gowon", "General Abdulsalami Abubakar"], 0, "Babangida created 9 states in August 1991 (Abia, Delta, Edo, Enugu, Jigawa, Kebbi, Kogi, Osun, Taraba and Yobe), making 30 states.", "Easy"),
    ("gov_m3_45", "Interim National Government 1993", "2011", "Following the annulment of the June 12, 1993 presidential election and Babangida's stepping aside, the Interim National Government (ING) was headed by:", ["Chief Ernest Shonekan", "Chief M.K.O. Abiola", "General Sani Abacha", "Ambassador Babagana Kingibe"], 0, "Chief Ernest Shonekan headed the short-lived civilian Interim National Government from August to November 1993.", "Easy"),
    ("gov_m3_46", "Military Rule: Abacha Regime 1993-1998", "2010", "The supreme legislative and executive ruling body during the military regime of General Sani Abacha was the:", ["Provisional Ruling Council (PRC)", "Armed Forces Ruling Council (AFRC)", "Supreme Military Council (SMC)", "National Security Council"], 0, "General Sani Abacha established the Provisional Ruling Council (PRC) as the highest organ of state power.", "Easy"),
    ("gov_m3_47", "State Creation: 1996 (36 States)", "2010", "Nigeria became a federation of 36 states on October 1, 1996 following the creation of six new states by:", ["General Sani Abacha", "General Abdulsalami Abubakar", "General Ibrahim Babangida", "General Yakubu Gowon"], 0, "General Sani Abacha created 6 new states in 1996 (Bayelsa, Ebonyi, Ekiti, Gombe, Nasarawa, and Zamfara), bringing Nigeria's total to 36 states.", "Easy"),
    ("gov_m3_48", "Fourth Republic: 1999 Transition", "2010", "The head of state who successfully conducted the transition elections and handed over power to a democratic government on May 29, 1999 was:", ["General Abdulsalami Abubakar", "General Sani Abacha", "General Ibrahim Babangida", "Chief Ernest Shonekan"], 0, "General Abdulsalami Abubakar oversaw the drafting of the 1999 Constitution and successfully transferred power to President Olusegun Obasanjo on May 29, 1999.", "Easy"),
    ("gov_m3_49", "Fourth Republic: Political Parties 1999", "2010", "The three political parties registered by INEC to contest the 1999 general elections that ushered in the Fourth Republic were:", ["PDP, APP (later ANPP), and AD", "PDP, APC, and APGA", "SDP, NRC, and PRP", "UPN, NPN, and NPP"], 0, "INEC registered the People's Democratic Party (PDP), All People's Party (APP), and Alliance for Democracy (AD) for the 1999 transition.", "Easy"),
    ("gov_m3_50", "Revenue Allocation: Commissions", "2010", "The permanent statutory body established by the 1999 Constitution to monitor fiscal allocation and determine remuneration of political office holders is the:", ["Revenue Mobilization Allocation and Fiscal Commission (RMAFC)", "National Planning Commission", "Federal Character Commission", "Fiscal Transparency Agency"], 0, "RMAFC monitors revenue accruals into the Federation Account, formulates allocation formulas, and fixes salaries of political and judicial officers.", "Easy")
]

